<?php

namespace App\Support\SiteCheck;

/**
 * Каталог на проверките при обхождането: тежест, област и обяснение на разбираем език.
 * Областите са петте в отчета: Техническо, Съдържание и заглавия, Видимост в AI, Локално и доверие, Проследяване.
 * Старите ключове (от първата версия на обхождането) са тук само с област; техният текст е в SiteCrawler::describe().
 */
class IssueCatalog
{
    public const AREAS = ['technical', 'content', 'ai', 'local', 'tracking'];

    /** key => [тежест, област] */
    public const META = [
        // Техническо
        'server_errors' => ['error', 'technical'], 'broken_pages' => ['error', 'technical'], 'broken_resources' => ['error', 'technical'],
        'mixed_content' => ['error', 'technical'], 'canonical_broken' => ['error', 'technical'], 'sitemap_bad' => ['error', 'technical'],
        'broken_external' => ['warning', 'technical'], 'redirect_chains' => ['warning', 'technical'], 'links_to_redirects' => ['warning', 'technical'],
        'canonical_missing' => ['warning', 'technical'], 'canonical_other' => ['warning', 'technical'], 'noindex' => ['warning', 'technical'],
        'images_heavy' => ['warning', 'technical'], 'slow_pages' => ['warning', 'technical'], 'deep_pages' => ['warning', 'technical'],
        'missing_from_sitemap' => ['warning', 'technical'],
        'dup_www' => ['warning', 'technical'], 'dup_http' => ['warning', 'technical'], 'dup_slash' => ['warning', 'technical'],
        'dup_index' => ['warning', 'technical'], 'dup_query' => ['warning', 'technical'],
        'canonical_redirect' => ['warning', 'technical'], 'canonical_other_host' => ['warning', 'technical'],
        'canonical_noindex' => ['warning', 'technical'], 'canonical_chain' => ['warning', 'technical'],
        'hreflang_invalid' => ['warning', 'technical'], 'hreflang_no_self' => ['warning', 'technical'], 'hreflang_no_return' => ['warning', 'technical'],
        'hreflang_no_default' => ['notice', 'technical'], 'hreflang_bad_target' => ['warning', 'technical'],
        'images_no_size' => ['warning', 'technical'], 'images_lcp_lazy' => ['warning', 'technical'], 'images_legacy' => ['notice', 'technical'],
        'orphan_pages' => ['warning', 'technical'], 'few_inlinks' => ['notice', 'technical'],
        'robots_missing' => ['notice', 'technical'], 'robots_no_sitemap' => ['notice', 'technical'], 'robots_blocks_assets' => ['warning', 'technical'],
        'sitemap_no_lastmod' => ['notice', 'technical'], 'sitemap_lastmod_future' => ['warning', 'technical'],
        'sitemap_too_big' => ['warning', 'technical'], 'sitemap_other_host' => ['warning', 'technical'],
        'no_hsts' => ['notice', 'technical'], 'no_security_headers' => ['notice', 'technical'], 'soft_404' => ['warning', 'technical'],
        'lang_missing' => ['warning', 'technical'], 'lang_mismatch' => ['warning', 'technical'],
        // Съдържание и заглавия
        'no_title' => ['error', 'content'], 'no_description' => ['error', 'content'],
        'title_duplicate' => ['warning', 'content'], 'title_length' => ['warning', 'content'], 'description_duplicate' => ['warning', 'content'],
        'description_length' => ['warning', 'content'], 'description_short' => ['notice', 'content'],
        'no_h1' => ['warning', 'content'], 'multiple_h1' => ['warning', 'content'], 'duplicate_h1' => ['warning', 'content'],
        'heading_skips' => ['notice', 'content'], 'title_equals_h1' => ['notice', 'content'],
        'images_no_alt' => ['warning', 'content'], 'thin_pages' => ['warning', 'content'], 'no_og' => ['warning', 'content'],
        'duplicate_content' => ['warning', 'content'], 'weak_anchors' => ['notice', 'content'],
        // Видимост в AI
        'no_schema' => ['warning', 'ai'], 'schema_invalid' => ['warning', 'ai'], 'schema_incomplete' => ['warning', 'ai'],
        'schema_no_org' => ['warning', 'ai'], 'schema_org_incomplete' => ['notice', 'ai'], 'schema_no_breadcrumb' => ['notice', 'ai'],
        'schema_faq_mismatch' => ['warning', 'ai'], 'llms_missing' => ['notice', 'ai'],
        // Локално и доверие
        'local_no_address' => ['notice', 'local'], 'local_no_map' => ['notice', 'local'], 'local_no_hours' => ['notice', 'local'],
        'trust_no_privacy' => ['warning', 'local'], 'trust_no_terms' => ['notice', 'local'], 'trust_no_contact' => ['warning', 'local'],
        // Проследяване
        'tracking_none' => ['notice', 'tracking'], 'tracking_no_consent' => ['notice', 'tracking'], 'tracking_old_ga' => ['warning', 'tracking'],
    ];

    public static function severity(string $key): string
    {
        return self::META[$key][0] ?? 'warning';
    }

    public static function area(string $key): string
    {
        return self::META[$key][1] ?? 'technical';
    }

    public static function areaLabel(string $area): string
    {
        return match ($area) {
            'technical' => __('Техническо'),
            'content' => __('Съдържание и заглавия'),
            'ai' => __('Видимост в AI'),
            'local' => __('Локално и доверие'),
            'tracking' => __('Проследяване'),
            default => $area,
        };
    }

    /** Кратко пояснение под името на областта. */
    public static function areaHint(string $area): string
    {
        return match ($area) {
            'technical' => __('Адреси, пренасочвания, езици, скорост и сигурност.'),
            'content' => __('Заглавия, описания, текстове и снимки.'),
            'ai' => __('Дали Google и AI асистентите разбират кои сте.'),
            'local' => __('Контакти, адрес, работно време и доверие.'),
            'tracking' => __('Измерване на посетителите и бисквитки.'),
            default => '',
        };
    }

    /** Бележките в примерите са неутрални (числа, адреси, кодове); няколко кратки фрази се превеждат тук. */
    public static function note(?string $note): ?string
    {
        return $note === null ? null : __($note);
    }

    /**
     * Заглавие и обяснение на проблем за езика на текущата заявка.
     *
     * @return array{title: string, why: string}
     */
    public static function describe(string $key, int $count): array
    {
        $n = $count;
        $t = match ($key) {
            'dup_www' => [__('Сайтът се отваря и със www, и без www (:n)', compact('n')), __('Един и същ сайт е достъпен на два адреса. Google ги вижда като две копия и разделя силата на връзките между тях. Нужно е едно пренасочване към основния адрес.')],
            'dup_http' => [__('Сайтът се отваря и през http, и през https без пренасочване (:n)', compact('n')), __('Старата незащитена версия остава жива като копие на сайта. Хората я виждат с предупреждение „Не е защитено“, а Google трябва да избира коя да показва.')],
            'dup_slash' => [__('Страница с два адреса, със и без наклонена черта в края (:n)', compact('n')), __('Двата адреса показват едно и също и нямат канонична връзка. Google може да ги брои за две страници и да раздели силата им.')],
            'dup_index' => [__('Началната страница се отваря и през index.php или index.html (:n)', compact('n')), __('Така началната страница има още едно копие. Нужно е пренасочване към основния адрес.')],
            'dup_query' => [__('Страници с параметри в адреса, които повтарят съдържание (:n)', compact('n')), __('Адреси с параметри показват същото съдържание без канонична връзка към чистия адрес. Google ги обхожда и разпилява вниманието си.')],
            'canonical_redirect' => [__('Канонична връзка към адрес, който пренасочва (:n)', compact('n')), __('Страницата сочи като главна версия адрес, който сам пренасочва другаде. Google получава противоречив сигнал и може да избере друга версия.')],
            'canonical_other_host' => [__('Канонична връзка към друг домейн (:n)', compact('n')), __('Страницата казва на Google, че главната ѝ версия е на друг сайт. Ако не е нарочно, страницата може да изчезне от резултатите.')],
            'canonical_noindex' => [__('Канонична връзка и noindex, които си противоречат (:n)', compact('n')), __('Едната настройка казва на Google да не показва страницата, другата да покаже друг адрес вместо нея. Google избира сам и често не е това, което искате.')],
            'canonical_chain' => [__('Вериги от канонични връзки (:n)', compact('n')), __('Страница А сочи към Б, а Б сочи към В. Google може да не следва веригата докрай. Всяка страница трябва да сочи направо към главната си версия.')],
            'hreflang_invalid' => [__('Невалидни кодове на езиците, hreflang (:n)', compact('n')), __('Кодът трябва да е като bg, en или en-gb. Грешен код като en-uk се игнорира и хората от друга държава могат да получат грешния език.')],
            'hreflang_no_self' => [__('Езикови версии без връзка към самите себе си (:n)', compact('n')), __('Всяка страница на няколко езика трябва да присъства и сама в списъка. Без това Google може да игнорира целия списък.')],
            'hreflang_no_return' => [__('Езикови версии без връзка в обратната посока (:n)', compact('n')), __('Българската страница сочи към английската, но английската не сочи обратно. Google изисква двете да сочат една към друга, иначе игнорира връзката.')],
            'hreflang_no_default' => [__('Няма адрес по подразбиране за другите езици, x-default (:n)', compact('n')), __('Това е страницата за хора, чийто език не предлагате. Не е задължително, но помага при сайт на няколко езика.')],
            'hreflang_bad_target' => [__('Езикова версия, която води към липсваща или скрита страница (:n)', compact('n')), __('Списъкът с езици сочи към адрес, който не работи или е скрит от Google. Така хората от другия език не стигат до страницата.')],
            'heading_skips' => [__('Заглавия с прескочени нива, например от H1 направо към H3 (:n)', compact('n')), __('Подредбата на заглавията е като съдържанието на книга. Когато нивата се прескачат, на Google и на четците за незрящи им е по-трудно да разберат структурата. Дребно, но лесно за оправяне.')],
            'title_equals_h1' => [__('Заглавието за Google е същото като основното заглавие на страниците (:n)', compact('n')), __('Не е грешка. Но заглавието в Google е шанс да добавите град, услуга или причина да се кликне. Често там има повече смисъл от простото повторение.')],
            'description_short' => [__('Описания, по-къси от 70 знака (:n)', compact('n')), __('Късото описание не използва мястото под заглавието в Google и казва малко на клиента защо да кликне.')],
            'duplicate_content' => [__('Страници с почти еднакъв текст (:n)', compact('n')), __('Когато две страници казват почти едно и също, Google показва само едната, а другата остава без посетители. Всяка страница трябва да отговаря на свой въпрос на клиента.')],
            'weak_anchors' => [__('Връзки без ясен текст, като тук, виж повече или празни (:n)', compact('n')), __('Текстът на връзката казва на Google и на незрящите накъде води тя. Връзка с текст тук не казва нищо. Пишете какво ще намери човекът, например цени на уебсайтове.')],
            'images_no_size' => [__('Страници със снимки без зададени ширина и височина (:n)', compact('n')), __('Когато браузърът не знае размера на снимката, страницата подскача, докато се зареди. Това дразни посетителя и влошава показателя CLS на Google.')],
            'images_lcp_lazy' => [__('Първата снимка се зарежда отложено (:n)', compact('n')), __('Отложеното зареждане е полезно за снимките по-надолу, но не и за първата. Тя се показва по-късно и страницата изглежда по-бавна, особено на телефон.')],
            'images_legacy' => [__('Малко снимки в съвременен формат, WebP или AVIF (:n)', compact('n')), __('WebP и AVIF са по-леки от JPG и PNG при същото качество. По-леките снимки правят страницата по-бърза, особено на мобилен интернет.')],
            'orphan_pages' => [__('Страници без нито една връзка към тях от сайта (:n)', compact('n')), __('Страницата е в картата на сайта, но никоя друга страница не води до нея. Посетителите не я намират, а Google я смята за по-маловажна.')],
            'few_inlinks' => [__('Страници с по-малко от 2 връзки към тях (:n)', compact('n')), __('Към страниците, към които сайтът рядко сочи, се стига трудно. Добавете връзки към тях от свързани страници и статии.')],
            'robots_missing' => [__('Няма файл robots.txt'), __('Файлът казва на търсачките какво могат да четат и къде е картата на сайта. Липсата му не е авария, но е лесно да се добави.')],
            'robots_no_sitemap' => [__('robots.txt не сочи към картата на сайта'), __('Един ред в robots.txt показва на Google и на AI търсачките къде е списъкът със страници. Не е задължително, но е препоръчително.')],
            'robots_blocks_assets' => [__('robots.txt спира стилове или скриптове на сайта (:n)', compact('n')), __('Когато Google не може да зареди стиловете и скриптовете, вижда страницата различно от хората и може да я оцени по-зле.')],
            'llms_missing' => [__('Няма файл llms.txt'), __('Това е нов и неофициален файл, който подрежда важните страници за AI асистентите. Не е изискване и не знаем да влияе на подреждането. Някои AI инструменти го четат, затова е евтин и безопасен допълнителен сигнал.')],
            'sitemap_no_lastmod' => [__('Картата на сайта няма дати на промяна (:n)', compact('n')), __('Датата на промяна помага на Google да реши кога да обходи страницата отново. Вярната дата е полезна, а измислената е по-лоша от никаква.')],
            'sitemap_lastmod_future' => [__('Картата на сайта има дати в бъдещето (:n)', compact('n')), __('Дата, която още не е настъпила, е явна грешка. Google може да започне да игнорира всички дати на сайта.')],
            'sitemap_too_big' => [__('Картата на сайта е по-голяма от позволеното (:n)', compact('n')), __('Един файл на картата може да съдържа до 50 000 адреса и до 50 MB. Над това Google не чете остатъка. Разделете я на няколко файла.')],
            'sitemap_other_host' => [__('Картата на сайта съдържа адреси от други домейни (:n)', compact('n')), __('Google игнорира адресите от друг домейн в картата. Най-често е грешка при пренасяне от тестов сайт или при смяна на домейна.')],
            'no_hsts' => [__('Няма HSTS, заглавка за винаги защитена връзка'), __('HSTS казва на браузъра да отваря сайта само през https. Дребно подобрение, което се включва на сървъра.')],
            'no_security_headers' => [__('Липсват защитни заглавки на сървъра (:n)', compact('n')), __('Това са настройки на сървъра, които защитават посетителите, например от вграждане на сайта в чужда страница. Не влияят пряко на Google, но са добра практика.')],
            'soft_404' => [__('Несъществуващ адрес отговаря като нормална страница'), __('Когато се напише адрес, който не съществува, сайтът отговаря успешно вместо с грешка 404. Google го нарича мека 404. Така в търсенето могат да попаднат празни страници.')],
            'lang_missing' => [__('Страници без обявен език (:n)', compact('n')), __('Атрибутът lang казва на браузъра и на четците за незрящи на какъв език е текстът. Без него преводачите и гласовите четци могат да сбъркат.')],
            'lang_mismatch' => [__('Обявеният език не съвпада с текста (:n)', compact('n')), __('Страницата казва, че е на един език, а текстът е на друг. Браузърите и четците могат да я прочетат погрешно, а езиковите сигнали към Google се объркват.')],
            'schema_invalid' => [__('Структурирани данни с грешка в кода, JSON-LD (:n)', compact('n')), __('Кодът за Google и AI е счупен и се игнорира напълно. Най-често е излишна запетая или кавичка. Поправя се за минути.')],
            'schema_incomplete' => [__('Структурирани данни без тип или контекст (:n)', compact('n')), __('Липсва указание какво описва кодът, тоест @type или @context. Търсачките не знаят какво да направят с него.')],
            'schema_no_org' => [__('Началната страница няма данни за фирмата, Organization или LocalBusiness'), __('Тези данни казват на Google и на AI асистентите коя е фирмата, къде е и как се свързват с нея. Помагат да ви представят вярно.')],
            'schema_org_incomplete' => [__('Данните за фирмата са непълни'), __('В описанието на фирмата липсват някои от полетата име, адрес, телефон и сайт, показани в примера. Те трябва да съвпадат с написаното на сайта.')],
            'schema_no_breadcrumb' => [__('Вътрешни страници без навигационна пътека, BreadcrumbList (:n)', compact('n')), __('Пътеката, като Начало, Услуги, Сайтове, може да се покаже в Google вместо дълъг адрес и помага на хората да разберат къде са.')],
            'schema_faq_mismatch' => [__('Въпроси в структурираните данни, които не се виждат на страницата (:n)', compact('n')), __('Данните за въпроси и отговори трябва да съвпадат с видимия текст. Скритото или несъвпадащо съдържание може да бъде игнорирано и намалява доверието.')],
            'local_no_address' => [__('Не открихме адрес на фирмата в текста на сайта'), __('Адресът в текста помага на клиентите да ви намерят и на Google да свърже сайта с мястото. Ако работите само онлайн, може да не ви трябва.')],
            'local_no_map' => [__('Не открихме карта или връзка към Google Maps'), __('Картата е най-бързият начин клиентът да види къде сте и как да стигне. Важна е, ако клиентите идват при вас.')],
            'local_no_hours' => [__('Не открихме работно време'), __('Клиентът иска да знае дали сте отворени. Работното време като текст или в данните за фирмата намалява излишните обаждания.')],
            'trust_no_privacy' => [__('Не открихме връзка към политика за поверителност'), __('Когато сайтът събира запитвания или имейли, хората очакват да видят как се пазят данните им. Липсата намалява доверието.')],
            'trust_no_terms' => [__('Не открихме връзка към общи условия'), __('За магазини и услуги с цени общите условия са очаквана част от доверието. Ако не са нужни за бизнеса ви, пренебрегнете това.')],
            'trust_no_contact' => [__('Контактите не са на един клик от началната страница'), __('Човекът, който е готов да се свърже, не бива да търси как. Видима връзка към контактите му спестява това.')],
            'tracking_none' => [__('Изглежда сайтът не измерва посетителите си'), __('Не открихме Google Analytics, Google Tag Manager или друг инструмент за измерване. Без измерване не знаете откъде идват запитванията. Възможно е да използвате начин, който не се вижда отвън.')],
            'tracking_no_consent' => [__('Изглежда проследяването работи без банер за бисквитки'), __('Открихме инструменти за проследяване, показани в примера, но не и инструмент за съгласие. Банерът може да се зарежда по начин, който не се вижда отвън, затова проверете сами как е настроен. Това не е правно становище.')],
            'tracking_old_ga' => [__('Изглежда още е включена старата версия на Google Analytics, UA'), __('Старата версия спря да събира данни през 2023 година. Ако това е единственото измерване, не получавате данни. Нужна е версията GA4.')],
            default => [$key, ''],
        };

        return ['title' => $t[0], 'why' => $t[1]];
    }
}
